/** A heatmap. MapLibre layer type `heatmap`. */
public class TileflowHeatmapLayer(id: String, public val source: String) : TileflowLayer(id, "heatmap") {
    /** The layer of a vector source to draw. */
    public var sourceLayer: String? = null

    /** Draws only the features this expression accepts. */
    public var filter: TileflowExpression? = null

    /** The zoom level from which the layer shows. */
    public var minZoom: Double? = null

    /** The zoom level from which the layer hides. */
    public var maxZoom: Double? = null

    /** Whether this layer is displayed. Default: `"visible"`. */
    public var visibility: TileflowValue<TileflowVisibility>? = null

    public fun visibility(value: TileflowVisibility): TileflowHeatmapLayer = apply {
        visibility = TileflowValue.constant(value)
    }

    public fun visibility(expression: TileflowExpression): TileflowHeatmapLayer = apply {
        visibility = TileflowValue.expression(expression)
    }

    /**
     * Radius of influence of one heatmap point in pixels. Increasing the value makes the heatmap
     * smoother, but less detailed. In pixels. At least 1. Default: `30`.
     */
    public var heatmapRadius: TileflowValue<Double>? = null

    public fun heatmapRadius(value: Double): TileflowHeatmapLayer = apply {
        heatmapRadius = TileflowValue.constant(value)
    }

    public fun heatmapRadius(expression: TileflowExpression): TileflowHeatmapLayer = apply {
        heatmapRadius = TileflowValue.expression(expression)
    }

    /** How [heatmapRadius] changes when it is set. */
    public var heatmapRadiusTransition: TileflowTransition? = null

    public fun heatmapRadiusTransition(transition: TileflowTransition): TileflowHeatmapLayer = apply {
        heatmapRadiusTransition = transition
    }

    /**
     * A measure of how much an individual point contributes to the heatmap. A value of 10 would be
     * equivalent to having 10 points of weight 1 in the same spot. Especially useful when combined
     * with clustering. At least 0. Default: `1`.
     */
    public var heatmapWeight: TileflowValue<Double>? = null

    public fun heatmapWeight(value: Double): TileflowHeatmapLayer = apply {
        heatmapWeight = TileflowValue.constant(value)
    }

    public fun heatmapWeight(expression: TileflowExpression): TileflowHeatmapLayer = apply {
        heatmapWeight = TileflowValue.expression(expression)
    }

    /**
     * Similar to `heatmap-weight` but controls the intensity of the heatmap globally. Primarily
     * used for adjusting the heatmap based on zoom level. At least 0. Default: `1`.
     */
    public var heatmapIntensity: TileflowValue<Double>? = null

    public fun heatmapIntensity(value: Double): TileflowHeatmapLayer = apply {
        heatmapIntensity = TileflowValue.constant(value)
    }

    public fun heatmapIntensity(expression: TileflowExpression): TileflowHeatmapLayer = apply {
        heatmapIntensity = TileflowValue.expression(expression)
    }

    /** How [heatmapIntensity] changes when it is set. */
    public var heatmapIntensityTransition: TileflowTransition? = null

    public fun heatmapIntensityTransition(transition: TileflowTransition): TileflowHeatmapLayer = apply {
        heatmapIntensityTransition = transition
    }

    /**
     * Defines the color of each pixel based on its density value in a heatmap. Should be an
     * expression that uses `["heatmap-density"]` as input. Default:
     * `["interpolate",["linear"],["heatmap-density"],0,"rgba(0, 0, 255,
     * 0)",0.1,"royalblue",0.3,"cyan",0.5,"lime",0.7,"yellow",1,"red"]`.
     */
    public var heatmapColor: TileflowValue<TileflowColor>? = null

    public fun heatmapColor(value: TileflowColor): TileflowHeatmapLayer = apply {
        heatmapColor = TileflowValue.constant(value)
    }

    public fun heatmapColor(expression: TileflowExpression): TileflowHeatmapLayer = apply {
        heatmapColor = TileflowValue.expression(expression)
    }

    /** The global opacity at which the heatmap layer will be drawn. From 0 to 1. Default: `1`. */
    public var heatmapOpacity: TileflowValue<Double>? = null

    public fun heatmapOpacity(value: Double): TileflowHeatmapLayer = apply {
        heatmapOpacity = TileflowValue.constant(value)
    }

    public fun heatmapOpacity(expression: TileflowExpression): TileflowHeatmapLayer = apply {
        heatmapOpacity = TileflowValue.expression(expression)
    }

    /** How [heatmapOpacity] changes when it is set. */
    public var heatmapOpacityTransition: TileflowTransition? = null

    public fun heatmapOpacityTransition(transition: TileflowTransition): TileflowHeatmapLayer = apply {
        heatmapOpacityTransition = transition
    }

    public fun minZoom(value: Double): TileflowHeatmapLayer = apply { minZoom = value }

    public fun maxZoom(value: Double): TileflowHeatmapLayer = apply { maxZoom = value }

    public fun slot(value: TileflowLayerSlot?): TileflowHeatmapLayer = apply { slot = value }

    public fun sourceLayer(value: String): TileflowHeatmapLayer = apply { sourceLayer = value }

    public fun filter(expression: TileflowExpression): TileflowHeatmapLayer = apply { filter = expression }

    override fun json(): org.json.JSONObject =
        styleLayerJson(
            this,
            source,
            sourceLayer,
            filter,
            minZoom,
            maxZoom,
            layout =
                listOf(
                "visibility" to visibility,
                ),
            paint =
                listOf(
                "heatmap-radius" to heatmapRadius,
                "heatmap-radius-transition" to heatmapRadiusTransition,
                "heatmap-weight" to heatmapWeight,
                "heatmap-intensity" to heatmapIntensity,
                "heatmap-intensity-transition" to heatmapIntensityTransition,
                "heatmap-color" to heatmapColor,
                "heatmap-opacity" to heatmapOpacity,
                "heatmap-opacity-transition" to heatmapOpacityTransition,
                ),
        )
