     * plane), respectively. In pixels. Default: `[0,0]`.
     */
    public var fillExtrusionTranslate: TileflowValue<List<Double>>? = null

    public fun fillExtrusionTranslate(value: List<Double>): TileflowFillExtrusionLayer = apply {
